public int FindFirstSetBitShift(int n)
{
    int pos = 1;
    while (n > 0)
    {
        if ((n & 1) == 1)
            return pos;
        n >>= 1;
        pos++;
    }
    return 0;
}

public int FindFirstSetBitTrick(int n)
{
    if (n == 0) return 0;
    int isolated = n & -n;
    return (int)Math.Log(isolated, 2) + 1;
}
